"""Minimal AlphaEvolve-like evolutionary loop — stdlib Python.

Toy symbolic regression. The "LLM" proposes a small mutation to a candidate
expression (change a constant, change an operator, add a term). The
"evaluator" scores the expression on training and held-out test points.

MAP-elites grid keeps diverse candidates: cell keyed by (expression depth,
constant magnitude bucket). Without a held-out split the loop overfits
aggressively; with one the best candidate generalizes.
"""

from __future__ import annotations

import argparse
import math
import random
from dataclasses import dataclass


DEFAULT_SEED = 1


# Target function the loop tries to rediscover.
def target(x: float) -> float:
    return 2.0 * x * x + 3.0 * x - 1.0


Expr = tuple  # recursive: ("num", v) | ("x",) | ("add", a, b) | ("mul", a, b)


def evaluate_expr(e: Expr, x: float) -> float:
    tag = e[0]
    if tag == "num":
        return float(e[1])
    if tag == "x":
        return x
    if tag == "add":
        return evaluate_expr(e[1], x) + evaluate_expr(e[2], x)
    if tag == "mul":
        return evaluate_expr(e[1], x) * evaluate_expr(e[2], x)
    raise ValueError(tag)


def depth(e: Expr) -> int:
    tag = e[0]
    if tag in ("num", "x"):
        return 1
    return 1 + max(depth(e[1]), depth(e[2]))


def max_const(e: Expr) -> float:
    tag = e[0]
    if tag == "num":
        return abs(e[1])
    if tag == "x":
        return 0.0
    return max(max_const(e[1]), max_const(e[2]))


def mutate(e: Expr) -> Expr:
    """Stand-in for the LLM's targeted edit."""
    choice = random.random()
    if choice < 0.25:
        return random_leaf()
    if choice < 0.5:
        return ("add", e, random_leaf())
    if choice < 0.75:
        return ("mul", e, random_leaf())
    # perturb a constant somewhere
    return perturb(e)


def perturb(e: Expr) -> Expr:
    tag = e[0]
    if tag == "num":
        return ("num", e[1] + random.choice([-1.0, -0.5, 0.5, 1.0]))
    if tag == "x":
        return e
    return (tag, perturb(e[1]), e[2]) if random.random() < 0.5 else (tag, e[1], perturb(e[2]))


def random_leaf() -> Expr:
    if random.random() < 0.5:
        return ("x",)
    return ("num", float(random.choice([-2, -1, 0, 1, 2, 3])))


def render(e: Expr) -> str:
    tag = e[0]
    if tag == "num":
        return f"{e[1]:g}"
    if tag == "x":
        return "x"
    op = "+" if tag == "add" else "*"
    return f"({render(e[1])} {op} {render(e[2])})"


def mse(e: Expr, xs: list[float]) -> float:
    total = 0.0
    for x in xs:
        try:
            y = evaluate_expr(e, x)
        except (OverflowError, ValueError):
            return float("inf")
        total += (y - target(x)) ** 2
    return total / max(1, len(xs))


@dataclass
class Candidate:
    expr: Expr
    train_score: float
    test_score: float
    generation: int


def cell_key(e: Expr) -> tuple[int, int]:
    d = min(depth(e), 6)
    c = min(int(max_const(e) / 2), 4)
    return (d, c)


def seed_candidate(test_xs: list[float], train_xs: list[float], gen: int) -> Candidate:
    e = random_leaf()
    return Candidate(e, mse(e, train_xs), mse(e, test_xs), gen)


def run_loop(
    generations: int,
    pop: int,
    use_holdout: bool,
    seed: int | None = None,
) -> tuple[Candidate, list[float], list[float]]:
    if seed is not None:
        random.seed(seed)
    train_xs = [-2.0, -1.0, 0.0, 1.0, 2.0, 3.0]
    test_xs = [-2.5, -1.5, -0.5, 0.5, 1.5, 2.5, 3.5]

    def signal_of(c: Candidate) -> float:
        return 0.5 * (c.train_score + c.test_score) if use_holdout else c.train_score

    archive: dict[tuple[int, int], Candidate] = {}
    for _ in range(pop):
        c = seed_candidate(test_xs, train_xs, 0)
        key = cell_key(c.expr)
        incumbent = archive.get(key)
        if incumbent is None or signal_of(c) < signal_of(incumbent):
            archive[key] = c

    best_trace: list[float] = []
    test_trace: list[float] = []
    for g in range(1, generations + 1):
        parent = random.choice(list(archive.values()))
        child_expr = mutate(parent.expr)
        tr = mse(child_expr, train_xs)
        te = mse(child_expr, test_xs)
        child = Candidate(child_expr, tr, te, g)
        key = cell_key(child_expr)
        incumbent = archive.get(key)
        if incumbent is None or signal_of(child) < signal_of(incumbent):
            archive[key] = child

        best = min(archive.values(), key=lambda c: c.train_score)
        best_trace.append(best.train_score)
        test_trace.append(best.test_score)

    # Final selection must use the same signal as the search: using the
    # held-out test here when use_holdout=False would silently leak the
    # holdout back into Run B and mask the overfitting the lesson shows.
    best = min(archive.values(), key=signal_of)
    return best, best_trace, test_trace


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--no-holdout",
        action="store_true",
        help="skip the held-out test evaluator (Run B only; forces reward-hacking demo)",
    )
    args = parser.parse_args()

    print("=" * 70)
    print("ALPHAEVOLVE-STYLE LOOP (Phase 15, Lesson 3)")
    print("=" * 70)
    print("target: 2x^2 + 3x - 1")

    if not args.no_holdout:
        print("\nRun A: held-out test included in evaluator signal")
        best, train_trace, _ = run_loop(
            generations=1500, pop=20, use_holdout=True, seed=DEFAULT_SEED
        )
        print(f"  best expr : {render(best.expr)}")
        print(f"  train MSE : {best.train_score:.4f}")
        print(f"  test  MSE : {best.test_score:.4f}")
        print(f"  generation: {best.generation}")
        print("  progress  : gen 100 train={:.3f} gen 500 train={:.3f} gen 1500 train={:.3f}".format(
            train_trace[99], train_trace[499], train_trace[-1]))

    print("\nRun B: no held-out test (train-only evaluator -> reward hacking risk)")
    best, _train_trace, _test_trace = run_loop(
        generations=1500, pop=20, use_holdout=False, seed=DEFAULT_SEED
    )
    print(f"  best expr : {render(best.expr)}")
    print(f"  train MSE : {best.train_score:.4f}")
    print(f"  test  MSE : {best.test_score:.4f}")
    print(f"  generation: {best.generation}")
    gap = best.test_score - best.train_score
    print(f"  train-to-test gap: {gap:+.4f}  (large gap = overfit/reward hacking proxy)")

    print()
    print("=" * 70)
    print("HEADLINE: the evaluator is the architecture")
    print("-" * 70)
    print("  Run A converges to low train AND low test MSE.")
    print("  Run B converges to low train MSE; test MSE stays loose or worse.")
    print("  A held-out evaluator is the difference between discovery and")
    print("  reward hacking. AlphaEvolve's wins are in domains where such an")
    print("  evaluator exists. Picking those domains is the hard part.")


if __name__ == "__main__":
    main()

// Lesson: AlphaEvolve: Evolutionary Coding Agents (phase 15 / lesson 03)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/15-autonomous-systems/03-alphaevolve-evolutionary-coding/docs/en.md
// Run: npx tsx phases/15-autonomous-systems/03-alphaevolve-evolutionary-coding/code/main.ts

let rngState = 0;

function seedRandom(value: number): void {
  rngState = value >>> 0;
}

function random(): number {
  rngState = (rngState + 0x6d2b79f5) >>> 0;
  let t = rngState;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

function choice<T>(items: T[]): T {
  return items[Math.floor(random() * items.length)];
}

function pyFixed(value: number, digits: number): string {
  if (!Number.isFinite(value)) return Number.isNaN(value) ? "nan" : value > 0 ? "inf" : "-inf";
  const rounded = value.toFixed(digits);
  const exact = Math.abs(value).toFixed(Math.min(100, digits + 60));
  const tail = exact.slice(exact.indexOf(".") + 1 + digits);
  const tie = /^50*$/.test(tail);
  if (!tie) return rounded;
  const down = (Math.trunc(Math.abs(value) * 10 ** digits) / 10 ** digits).toFixed(digits);
  const lastDigit = Number(down.replace(".", "").slice(-1));
  const magnitude = lastDigit % 2 === 0 ? down : (Number(down) + 10 ** -digits).toFixed(digits);
  return value < 0 ? `-${magnitude}` : magnitude;
}


const DEFAULT_SEED = 12;

function target(x: number): number {
  return 2.0 * x * x + 3.0 * x - 1.0;
}

type Expr = ["num", number] | ["x"] | ["add", Expr, Expr] | ["mul", Expr, Expr];

function evaluateExpr(e: Expr, x: number): number {
  switch (e[0]) {
    case "num":
      return e[1];
    case "x":
      return x;
    case "add":
      return evaluateExpr(e[1], x) + evaluateExpr(e[2], x);
    case "mul":
      return evaluateExpr(e[1], x) * evaluateExpr(e[2], x);
  }
}

function depth(e: Expr): number {
  if (e[0] === "num" || e[0] === "x") return 1;
  return 1 + Math.max(depth(e[1]), depth(e[2]));
}

function maxConst(e: Expr): number {
  if (e[0] === "num") return Math.abs(e[1]);
  if (e[0] === "x") return 0.0;
  return Math.max(maxConst(e[1]), maxConst(e[2]));
}

function mutate(e: Expr): Expr {
  const pick = random();
  if (pick < 0.25) return randomLeaf();
  if (pick < 0.5) return ["add", e, randomLeaf()];
  if (pick < 0.75) return ["mul", e, randomLeaf()];
  return perturb(e);
}

function perturb(e: Expr): Expr {
  if (e[0] === "num") return ["num", e[1] + choice([-1.0, -0.5, 0.5, 1.0])];
  if (e[0] === "x") return e;
  return random() < 0.5 ? [e[0], perturb(e[1]), e[2]] : [e[0], e[1], perturb(e[2])];
}

function randomLeaf(): Expr {
  if (random() < 0.5) return ["x"];
  return ["num", choice([-2, -1, 0, 1, 2, 3])];
}

function render(e: Expr): string {
  if (e[0] === "num") return String(e[1]);
  if (e[0] === "x") return "x";
  const op = e[0] === "add" ? "+" : "*";
  return `(${render(e[1])} ${op} ${render(e[2])})`;
}

function mse(e: Expr, xs: number[]): number {
  let total = 0.0;
  for (const x of xs) {
    const y = evaluateExpr(e, x);
    total += (y - target(x)) ** 2;
  }
  return total / Math.max(1, xs.length);
}

interface Candidate {
  expr: Expr;
  train_score: number;
  test_score: number;
  generation: number;
}

function cellKey(e: Expr): string {
  const d = Math.min(depth(e), 6);
  const c = Math.min(Math.trunc(maxConst(e) / 2), 4);
  return `${d},${c}`;
}

function seedCandidate(testXs: number[], trainXs: number[], gen: number): Candidate {
  const e = randomLeaf();
  return { expr: e, train_score: mse(e, trainXs), test_score: mse(e, testXs), generation: gen };
}

function minBy<T>(items: T[], key: (item: T) => number): T {
  let best = items[0];
  for (const item of items.slice(1)) {
    if (key(item) < key(best)) best = item;
  }
  return best;
}

function runLoop(generations: number, pop: number, useHoldout: boolean, seed: number | null = null): [Candidate, number[], number[]] {
  if (seed !== null) seedRandom(seed);
  const trainXs = [-2.0, -1.0, 0.0, 1.0, 2.0, 3.0];
  const testXs = [-2.5, -1.5, -0.5, 0.5, 1.5, 2.5, 3.5];

  const signalOf = (c: Candidate): number => (useHoldout ? 0.5 * (c.train_score + c.test_score) : c.train_score);

  const archive = new Map<string, Candidate>();
  for (let i = 0; i < pop; i++) {
    const c = seedCandidate(testXs, trainXs, 0);
    const key = cellKey(c.expr);
    const incumbent = archive.get(key);
    if (incumbent === undefined || signalOf(c) < signalOf(incumbent)) archive.set(key, c);
  }

  const bestTrace: number[] = [];
  const testTrace: number[] = [];
  for (let g = 1; g <= generations; g++) {
    const parent = choice([...archive.values()]);
    const childExpr = mutate(parent.expr);
    const tr = mse(childExpr, trainXs);
    const te = mse(childExpr, testXs);
    const child: Candidate = { expr: childExpr, train_score: tr, test_score: te, generation: g };
    const key = cellKey(childExpr);
    const incumbent = archive.get(key);
    if (incumbent === undefined || signalOf(child) < signalOf(incumbent)) archive.set(key, child);

    const best = minBy([...archive.values()], (c) => c.train_score);
    bestTrace.push(best.train_score);
    testTrace.push(best.test_score);
  }

  const best = minBy([...archive.values()], signalOf);
  return [best, bestTrace, testTrace];
}

function main(): void {
  const noHoldout = process.argv.slice(2).includes("--no-holdout");

  console.log("=".repeat(70));
  console.log("ALPHAEVOLVE-STYLE LOOP (Phase 15, Lesson 3)");
  console.log("=".repeat(70));
  console.log("target: 2x^2 + 3x - 1");

  if (!noHoldout) {
    console.log("\nRun A: held-out test included in evaluator signal");
    const [best, trainTrace] = runLoop(1500, 20, true, DEFAULT_SEED);
    console.log(`  best expr : ${render(best.expr)}`);
    console.log(`  train MSE : ${pyFixed(best.train_score, 4)}`);
    console.log(`  test  MSE : ${pyFixed(best.test_score, 4)}`);
    console.log(`  generation: ${best.generation}`);
    console.log(
      `  progress  : gen 100 train=${pyFixed(trainTrace[99], 3)} gen 500 train=${pyFixed(trainTrace[499], 3)} gen 1500 train=${pyFixed(trainTrace[trainTrace.length - 1], 3)}`,
    );
  }

  console.log("\nRun B: no held-out test (train-only evaluator -> reward hacking risk)");
  const [best] = runLoop(1500, 20, false, DEFAULT_SEED);
  console.log(`  best expr : ${render(best.expr)}`);
  console.log(`  train MSE : ${pyFixed(best.train_score, 4)}`);
  console.log(`  test  MSE : ${pyFixed(best.test_score, 4)}`);
  console.log(`  generation: ${best.generation}`);
  const gap = best.test_score - best.train_score;
  console.log(`  train-to-test gap: ${gap >= 0 ? "+" : ""}${pyFixed(gap, 4)}  (large gap = overfit/reward hacking proxy)`);

  console.log();
  console.log("=".repeat(70));
  console.log("HEADLINE: the evaluator is the architecture");
  console.log("-".repeat(70));
  console.log("  Run A converges to low train AND low test MSE.");
  console.log("  Run B converges to low train MSE; test MSE stays loose or worse.");
  console.log("  A held-out evaluator is the difference between discovery and");
  console.log("  reward hacking. AlphaEvolve's wins are in domains where such an");
  console.log("  evaluator exists. Picking those domains is the hard part.");
}

main();

export {};
